import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·18","description":"易小帖 - 卷四·18","frontmatter":{"title":"卷四·18","description":"易小帖 - 卷四·18"},"headers":[],"relativePath":"classics/yixiaotie/112.md","filePath":"classics/yixiaotie/112.md"}'),o={name:"classics/yixiaotie/112.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·18",tabindex:"-1"},[r("卷四·18 "),e("a",{class:"header-anchor",href:"#卷四·18","aria-label":"Permalink to “卷四·18”"},"​")],-1),e("p",null,"大衍方位合以《大傳》之卦位而生卦數，故乾六坎一艮八震三巽七離二坤九兌四，此自然定數，確不可易。如乾與坤對，乾為太陽，其數宜九，坤居太陰，其數宜六，似當一如卦爻之以陽為九，陰為六，而乃乾反居六，坤反居九以相對，而恰相反。此正陰陽交互，剛柔相錯之至變，而實至當者。其他坎之一，以一陽在中也。離之二，以一陰在中也。陰以二為一，二偶數即一陰也。震之三則震以長男而當參天之位，為陽之始，兌之四則兌以少女而當兩地之位為陰之終，以兩合一曰參，以兩合兩曰兩也。至若巽為長女而近陽之盡，故七艮為少男，而近陰之盡，故八。此皆相對相合，雖依位生數而自然不易之理在其中焉。若先天卦位則以方圖言之，兌為太陽，震為少陰，巽為少陽，艮為太陰，已屬不通，而以觀其數，乾一兌九，則九不通離二震八，則八無理。巽三坎七，則三七難明。艮四坤六，則四六何解。至以圓圖言之，則又乾七兌二離八震三巽四坎九艮一坤六，以乾居少陽，坤居太陰，艮居太陽，兌居少陰，震居少陽，巽居太陰，坎居太陽，離居少陰，其不通倍甚。故韓邦奇曰：方圓之可怪，如一六老陽，二七少陽。三八少陰，四九太陰。其於六七八九是矣。若一二三四，則何為哉？張南士亦曰：卦位之數，即天地生成之數也。生數居四正，成數居四維，相得而各合，其義瞭然。故坎北一，離南二，震東三，兌西四，乾西北六，巽東南七，艮西北八，坤西南九。攧撲不破。今以乾居正南當七，坤居正北當六，離居正東當八，坎居正西當九，則竟以大衍成數居四正，而以艮居西北當一，兌居東南當二，震居東北當三，巽居西南當四，則又以大衍生數居四維，而卦位之配，俱於陰陽奇偶大不相合，此非外氏誣罔所為而何？",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
